extractData() {
  const data = {};
  // Get title
  data.title = document.querySelector('h1')?.textContent?.trim();
  // Get description
  data.description = document.querySelector('meta[name="description"]')?.getAttribute('content');
  // Get ingredients
  const ingredientEls = document.querySelectorAll('.mntl-structured-ingredients__list-item, [data-ingredient-name]');
  data.ingredients = Array.from(ingredientEls).map(el => el.textContent.trim().replace(/\s+/g, ' ')).slice(0, 30);
  // Get instructions
  const stepEls = document.querySelectorAll('#recipe__steps .mntl-sc-block-html p, .recipe-instructions__list-item, [data-instruction-text]');
  data.steps = Array.from(stepEls).map(el => el.textContent.trim().replace(/\s+/g, ' ')).slice(0, 30);
  // Get times
  const timeEls = document.querySelectorAll('.mntl-recipe-details__value, .recipe-details__value');
  data.times = Array.from(timeEls).map(el => el.textContent.trim()).slice(0, 10);
  return data;
} return extractData();

