function getData() {
  const data = {};
  data.title = document.querySelector('h1')?.textContent?.trim() || '';
  const ingredientEls = document.querySelectorAll('.mm-recipes-structured-ingredients__list-item');
  data.ingredients = Array.from(ingredientEls).map(el => el.textContent.trim().replace(/\s+/g, ' '));
  const stepEls = document.querySelectorAll('#mm-recipes-steps__content_1-0 p, .mm-recipes-steps__content p, #recipe__steps p');
  if (stepEls.length === 0) {
    const stepContainers = document.querySelectorAll('.mm-recipes-steps__content');
    data.steps = Array.from(stepContainers).map(el => el.innerText.trim());
  } else {
    data.steps = Array.from(stepEls).map(el => el.textContent.trim().replace(/\s+/g, ' '));
  }
  return JSON.stringify(data);
}
return getData();

function getTimes() {
  const items = document.querySelectorAll('.mm-recipes-details__item, .recipe-details__item');
  const result = [];
  items.forEach(item => {
    const label = item.querySelector('.mm-recipes-details__label, .recipe-details__label')?.textContent?.trim() || '';
    const value = item.querySelector('.mm-recipes-details__value, .recipe-details__value')?.textContent?.trim() || '';
    if (label || value) result.push(label + ': ' + value);
  });
  if (result.length === 0) {
    // try alternate
    const dt = document.querySelector('.mntl-recipe-details__content')?.innerText;
    return dt || 'no items found';
  }
  return result.join(' | ');
}
return getTimes();
